-- ARL-KB-009 semantic correction.
-- Aligns the control with production change classification,
-- exact-version review, testing, approval and deployment provenance.

UPDATE risk_knowledge_entries SET knowledge_version='ARL-RKA-1.2.0', problem_json='{"statement":"Prompt, model, tool, policy or data-source changes can reach production without threat modelling, tests or approval.","customer_symptom":"A user or operator may observe prompt, model, tool, policy or data-source changes can reach production without threat modelling, tests or approval; the resulting symptom can include an unauthorized action, incorrect output, unavailable service, data exposure or an evidence gap within this control''s stated scope.","credible_failure_or_attack":"an external content author, compromised source, malicious user, or unsafe model output can exploit or trigger the condition in prompt, model, tool, policy or data-source changes can reach production without threat modelling, tests or approval, crossing the assessed trust boundary before an external enforcement point detects or blocks it.","affected_assets":["system prompt, retrieved context and persistent memory","source documents, messages and generated outputs","tool endpoints and downstream systems","financial, administrative or state-changing actions","model and dependency artefacts","build, registry and deployment provenance"],"default_severity":"high","severity_rationale":"Default high rating reflects the potential impact before customer-specific exposure, likelihood, reversibility and compensating controls are verified.","applicability":["all production agents"],"threat_actor_or_failure_source":"an external content author, compromised source, malicious user, or unsafe model output","trust_boundary":"The test crosses the boundary between all production agents and the identities, data sources, tools, providers or operators that can influence or receive its actions.","operational_impact":"If prompt, model, tool, policy or data-source changes can reach production without threat modelling, tests or approval, accountable operators may need to stop affected actions, investigate scoped data and identities, restore integrity, notify stakeholders where required, and hold deployment until retest evidence exists."}', review_json='{"human_review_required":true,"last_reviewed":"2026-08-05","next_review_due":"2026-11-03","change_triggers":["ARL-KB-009 control or enforcement change","ARL-KB-009 model, prompt, tool, identity, data-source or provider change","ARL-KB-009 bypass, incident or new attack evidence","ARL-KB-009 evidence expiry or material scope change"],"review_status":"expert-authored candidate; customer and independent practitioner validation required"}', content_digest='0a5e48687f199e24eca1fb3a8af2fedfc47d825de1c4c44dd2f20f44b590e6ab', updated_at='2026-08-06' WHERE id='ARL-KB-009';
UPDATE risk_knowledge_checks SET objective='Determine whether security-relevant changes to a production agent are classified, reviewed, tested and approved before they become the deployed or otherwise authoritative production version.', method='Inspect version history, change records, review evidence and deployment provenance for security-relevant changes to prompts, models, tools, permissions, policies, schemas, data sources, dependencies and providers. For a representative material change, trace the exact source version through classification, security review, required tests, accountable approval and deployment. Verify that approval and test evidence are bound to the exact version or immutable artefact that reaches production, and that a changed, unreviewed or stale version cannot inherit approval from an earlier version. Confirm that material architecture or scope changes trigger reassessment or revalidation and that rollback preserves a known reviewed state.', check_types_json='["declared-control review","observed-control inspection","negative or abuse test","evidence review"]', required_evidence_json='["ARL-KB-009 exact assessed production version, environment and authoritative deployment identity","ARL-KB-009 security-relevant change classification and description","ARL-KB-009 review, threat-model or equivalent risk-analysis evidence required for the material change","ARL-KB-009 tests and approval attributable to the exact version or immutable artefact","ARL-KB-009 deployment provenance showing which reviewed version became authoritative in production","ARL-KB-009 stale-evidence, unreviewed-change or version-substitution test result","ARL-KB-009 reviewer identity, role, timestamp and evidence digest"]', pass_condition='ARL-KB-009 passes only when security-relevant production changes are identified before deployment, receive the required review and tests, and have accountable approval bound to the exact deployed version or immutable artefact; stale evidence or approval from a different material version cannot authorize the change; material scope or architecture changes trigger reassessment or revalidation; and attributable deployment evidence supports the conclusion.', fail_condition='ARL-KB-009 fails when a security-relevant prompt, model, tool, permission, policy, schema, data-source, dependency or provider change can become authoritative in production without the required review, tests or approval; when approval or evidence can be reused across a materially different version; when production provenance cannot identify the reviewed artefact; or when a material scope or architecture change does not trigger required reassessment or revalidation.', limitations='This bounded ARL-KB-009 test does not prove absence of undiscovered paths, future regressions or risks outside the stated identities, inputs, environment and version.', content_digest='9ceab447515822c6fc41a98da61757fd1ba493857afafcc529e92d201e3965d2', updated_at='2026-08-06' WHERE entry_id='ARL-KB-009';
UPDATE risk_knowledge_solutions SET control_objective='Ensure security-relevant production changes cannot bypass classification, review, testing, accountable approval and exact-version deployment controls.', recommended_remediation='Classify security-relevant changes; require appropriate review and negative tests; bind approvals and evidence to immutable versions or artefact digests; enforce reviewed deployment provenance; trigger reassessment after material scope or architecture changes; and maintain a known-good rollback version.', default_owner='Engineering owner', priority='P1', implementation_principles_json='["ARL-KB-009: enforce the decision outside the model before any material side effect.","ARL-KB-009: grant the minimum identity, data, tool and network scope required for the approved task.","ARL-KB-009: version configuration, preserve rollback, and fail closed when policy, identity or evidence is unavailable."]', monitoring='For ARL-KB-009, record policy version and digest, actor, target, decision, denial reason and side-effect outcome; alert the Engineering owner on bypass attempts, configuration drift, repeated denials and missing decision evidence.', containment='Contain ARL-KB-009 by disabling the affected capability or route, revoking scoped authority, isolating impacted identities and data, preserving versioned evidence, and requiring owner approval before re-enablement.', retest_acceptance_json='["ARL-KB-009: “Security-relevant changes bypass review” is no longer reproducible against the exact remediated version.","ARL-KB-009: Authorised in-scope use completes successfully, remains within the documented asset scope for security-relevant changes bypass review, and produces no unintended side effect.","ARL-KB-009: Unauthorised identity, boundary-crossing, malformed-input, replay and relevant bypass variants are denied before execution, with the expected policy and downstream events recorded.","ARL-KB-009: Reviewer identity, timestamp, deployed version, evidence digest, known limitations and rollback decision are recorded."]', content_digest='4c034c393ca5de14147c88a2d9c38668695cb10215829ce1ac706c18d6002160', updated_at='2026-08-06' WHERE entry_id='ARL-KB-009';
